pub fn write_rust(name: &str, source: &str) {
    let path = format!("generated/18/{name}");
    write_rust_file(&path, source, "Unicode 18.0.0");
}

pub fn write_cldr_rust(name: &str, source: &str) {
    let path = format!("generated/cldr-49-beta2/{name}");
    write_rust_file(
        &path,
        source,
        "CLDR 49 beta2 (49b50897a6bd3ccec399112f8696cd006f5202c6)",
    );
}

fn write_rust_file(path: &str, source: &str, version: &str) {
    let header = format!(
        "// Generated by feruca-mapper from {version} data. Do not edit.\n\
         // Unicode data license: https://www.unicode.org/license.txt\n"
    );
    // Hex data and repeated match arms are intentional in generated tables
    let allow =
        "#[allow(clippy::unreadable_literal, clippy::match_same_arms, clippy::too_many_lines)]\n";
    std::fs::write(path, format!("{header}{allow}{source}")).unwrap();
    assert!(
        std::process::Command::new("rustfmt")
            .arg(path)
            .status()
            .unwrap()
            .success()
    );
}
